import java.io.*;
import java.util.*;

public class CF1187G extends PrintWriter {
    CF1187G() { super(System.out); }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 15];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) { in = stream; }

        private int read() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            while ((c = read()) <= 32) if (c == -1) return -1;
            int val = 0;
            do {
                val = val * 10 + c - '0';
            } while ((c = read()) > 32);
            return val;
        }
    }

    FastScanner sc;

    public static void main(String[] args) {
        CF1187G solver = new CF1187G();
        solver.sc = new FastScanner(System.in);
        solver.run();
        solver.flush();
    }

    static final int INF = 0x3f3f3f3f;
    ArrayList<Integer>[] graph;
    int nNodes, nEdges;
    int[] potential, dist, prevEdge;
    int[] from, to, xorMask, edgeCost;
    int[] capacity;

    void initialize(int nodes, int edges) {
        graph = new ArrayList[nodes];
        for (int i = 0; i < nodes; i++) graph[i] = new ArrayList<>();
        potential = new int[nodes];
        dist = new int[nodes];
        prevEdge = new int[nodes];
        from = new int[edges];
        to = new int[edges];
        xorMask = new int[edges];
        edgeCost = new int[edges];
        capacity = new int[edges * 2];
        nEdges = 0;
    }

    void addEdge(int u, int v, int cap, int cost) {
        int idx = nEdges++;
        from[idx] = u;
        to[idx] = v;
        xorMask[idx] = u ^ v;
        edgeCost[idx] = cost;
        capacity[idx * 2] = cap;
        graph[u].add(idx * 2);
        graph[v].add(idx * 2 + 1);
    }

    int[] queue;
    int queueHead, queueTail, queueSize;
    boolean[] inQueue;

    void addToQueue(int node) {
        if (inQueue[node]) return;
        if (queueHead + queueTail == queue.length) {
            if (queueSize * 2 <= queue.length) {
                System.arraycopy(queue, queueHead, queue, 0, queueSize);
            } else {
                int[] newQueue = new int[queue.length * 2];
                System.arraycopy(queue, queueHead, newQueue, 0, queueSize);
                queue = newQueue;
            }
            queueHead = 0;
        }
        queue[queueHead + queueTail++] = node;
        inQueue[node] = true;
    }

    int removeFromQueue() {
        int node = queue[queueHead++];
        queueSize--;
        inQueue[node] = false;
        return node;
    }

    boolean spfa(int source, int sink) {
        Arrays.fill(potential, INF);
        potential[source] = 0;
        queueHead = queueTail = 0;
        addToQueue(source);

        while (queueSize > 0) {
            int u = removeFromQueue();
            int newDist = dist[u] + 1;

            for (int edgeIndex : graph[u]) {
                if (capacity[edgeIndex] > 0) {
                    int edgeId = edgeIndex >> 1;
                    int cost = (edgeIndex & 1) == 0 ? edgeCost[edgeId] : -edgeCost[edgeId];
                    int newPotential = potential[u] + cost;
                    int v = u ^ xorMask[edgeId];

                    if (potential[v] > newPotential || 
                        (potential[v] == newPotential && dist[v] > newDist)) {
                        potential[v] = newPotential;
                        dist[v] = newDist;
                        prevEdge[v] = edgeIndex;
                        addToQueue(v);
                    }
                }
            }
        }
        return potential[sink] != INF;
    }

    void augmentPath(int source, int sink) {
        int minCapacity = INF;
        for (int v = sink; v != source; v ^= xorMask[prevEdge[v] >> 1]) {
            minCapacity = Math.min(minCapacity, capacity[prevEdge[v]]);
        }
        for (int v = sink; v != source; v ^= xorMask[prevEdge[v] >> 1]) {
            int idx = prevEdge[v];
            capacity[idx] -= minCapacity;
            capacity[idx ^ 1] += minCapacity;
        }
    }

    void augmentPathUnit(int source, int sink) {
        for (int v = sink; v != source; v ^= xorMask[prevEdge[v] >> 1]) {
            int idx = prevEdge[v];
            capacity[idx]--;
            capacity[idx ^ 1]++;
        }
    }

    int minCostMaxFlow(int source, int sink) {
        while (spfa(source, sink)) {
            augmentPathUnit(source, sink);
        }
        int totalCost = 0;
        for (int i = 0; i < nEdges; i++) {
            totalCost += edgeCost[i] * capacity[i * 2 + 1];
        }
        return totalCost;
    }

    void run() {
        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();
            int c = sc.nextInt();
            int d = sc.nextInt();

            int[] specialNodes = new int[k];
            for (int i = 0; i < k; i++) {
                specialNodes[i] = sc.nextInt() - 1;
            }

            ArrayList<Integer>[] adj = new ArrayList[n];
            for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = sc.nextInt() - 1;
                int v = sc.nextInt() - 1;
                adj[u].add(v);
                adj[v].add(u);
            }

            int timeHorizon = k + 1;
            int totalNodes = n * timeHorizon + 1;
            int totalEdges = k + (m * 2 * k + n) * (timeHorizon - 1);

            initialize(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < timeHorizon - 1; t++) {
                    int u = i * timeHorizon + t;
                    for (int neighbor : adj[i]) {
                        int v = neighbor * timeHorizon + t + 1;
                        for (int x = 1; x <= k; x++) {
                            addEdge(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < timeHorizon - 1; t++) {
                    int u = i * timeHorizon + t;
                    int v = u + 1;
                    addEdge(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                addEdge(totalNodes - 1, specialNodes[i] * timeHorizon, 1, 0);
            }

            println(minCostMaxFlow(totalNodes - 1, 0 * timeHorizon + timeHorizon - 1));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}
